<template><ForgeDialog title="HTTP status codes" description="Search standard response codes by number, name or meaning." eyebrow="WORKSPACE / NETWORK" wide @close="emit('close')"><div class="status-panel"><input v-model="query" autofocus placeholder="Search 404, not found, redirect…" /><div class="status-list"><section v-for="category in filtered" :key="category.category"><h3>{{ category.category }}</h3><article v-for="item in category.codes" :key="item.code"><b>{{ item.code }}</b><span><strong>{{ item.name }} · {{ item.type }}</strong><small>{{ item.description }}</small></span></article></section><p v-if="!filtered.length" class="empty-copy">No status codes match.</p></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { codesByCategories } from '@/components/Tools/HTTPStatusCodes/http-status-codes.constants'
const emit=defineEmits<{close:[]}>(); const query=ref(''); const filtered=computed(()=>codesByCategories.map(category=>({...category,codes:category.codes.filter(i=>(i.code+' '+i.name+' '+i.description+' '+i.type+' '+category.category).toLowerCase().includes(query.value.toLowerCase()))})).filter(category=>category.codes.length))
</script>
<style scoped>.status-panel{display:grid;gap:12px}.status-panel>input{padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.status-list{display:grid;gap:6px;max-height:430px;overflow:auto}.status-list article{display:grid;grid-template-columns:54px 1fr;gap:12px;padding:10px;border:1px solid var(--pqt-border);border-radius:7px}.status-list article>b{color:var(--pqt-accent);font:16px var(--pqt-font-mono)}.status-list span{display:grid;gap:4px}.status-list small{color:var(--pqt-text-muted)}</style>
